 columns=contentW>=440?4:contentW>=300?3:contentW>=180?2:1;int gap=7;cardWidth=Math.min(108,(contentW-(columns-1)*gap)/columns);int gridX=contentX+(contentW-cardWidth*columns-gap*(columns-1))/2;int top=y+94,bottom=y+h-12,cardH=Math.min(96,Math.max(48,bottom-top));int visible=Math.max(1,(bottom-top+gap)/(cardH+gap));int rows=(list.size()+columns-1)/columns;scroll=Math.max(0,Math.min(scroll,Math.max(0,rows-visible)));
